/**
* Server-Side AI handler for BloomBuddy.
* Executes strictly on the server runtime — API keys are NEVER sent to or visible in client browser code.
*/
async function handleBloomBuddyRequest(data) {
	const geminiKey = process.env["GEMINI_API_KEY"]?.trim();
	const ollamaHost = process.env["OLLAMA_HOST"]?.trim() || "http://127.0.0.1:11434";
	const lmStudioHost = process.env["LM_STUDIO_HOST"]?.trim() || "http://127.0.0.1:1234";
	const systemPrompt = buildSystemPrompt(data);
	const lastUserMessage = data.messages[data.messages.length - 1]?.content || "";
	if (geminiKey) try {
		return {
			success: true,
			configured: true,
			provider: "gemini",
			reply: await callGeminiApi(geminiKey, systemPrompt, data.messages),
			sourceCitations: detectDocumentCitations(data.documentContext?.extractedText, lastUserMessage)
		};
	} catch (err) {
		const msg = err instanceof Error ? err.message : String(err);
		console.error("BloomBuddy Gemini error:", msg);
		return {
			success: false,
			configured: true,
			provider: "gemini",
			errorMessage: msg.includes("429") ? "Gemini rate limit reached. Please wait a moment before asking again." : msg.includes("403") || msg.includes("API key not valid") ? "Invalid GEMINI_API_KEY. Please verify your key at https://aistudio.google.com/app/apikey" : `AI service error: ${msg}`
		};
	}
	try {
		const ollamaRes = await fetch(`${ollamaHost}/api/tags`, { signal: AbortSignal.timeout(1200) }).catch(() => null);
		if (ollamaRes && ollamaRes.ok) return {
			success: true,
			configured: true,
			provider: "ollama",
			reply: await callOllamaApi(ollamaHost, systemPrompt, data.messages),
			sourceCitations: detectDocumentCitations(data.documentContext?.extractedText, lastUserMessage)
		};
	} catch {}
	try {
		const lmRes = await fetch(`${lmStudioHost}/v1/models`, { signal: AbortSignal.timeout(1200) }).catch(() => null);
		if (lmRes && lmRes.ok) return {
			success: true,
			configured: true,
			provider: "lmstudio",
			reply: await callLmStudioApi(lmStudioHost, systemPrompt, data.messages),
			sourceCitations: detectDocumentCitations(data.documentContext?.extractedText, lastUserMessage)
		};
	} catch {}
	return {
		success: false,
		configured: false,
		provider: "none",
		setupInstructions: "No live AI provider configured. Add GEMINI_API_KEY=your_key in .env (get a free key at https://aistudio.google.com/app/apikey) or start Ollama/LM Studio locally.",
		reply: data.preferences.language === "ml" ? "BloomBuddy AI തയ്യാറാണ്, എന്നാൽ സെർവറിൽ AI കീ നൽകിയിട്ടില്ല. ലൈവ് AI ഉത്തരങ്ങൾ ലഭിക്കുന്നതിന് .env ഫയലിൽ GEMINI_API_KEY ചേർക്കുക." : "BloomBuddy AI is ready, but no live AI model is configured on the server yet. To enable live answers, add GEMINI_API_KEY to your .env file or run Ollama/LM Studio locally."
	};
}
