/**
* Google Gemini REST API Client
*/
async function callGeminiApi(apiKey, systemInstruction, messages) {
	const url = `https://generativelanguage.googleapis.com/v1beta/models/gemini-2.0-flash:generateContent?key=${apiKey}`;
	const contents = [
		{
			role: "user",
			parts: [{ text: systemInstruction }]
		},
		{
			role: "model",
			parts: [{ text: "Understood. I am BloomBuddy, your supportive AI study companion. I will follow your guidance on language, explanation level, and document context." }]
		},
		...messages.slice(-8).map((m) => ({
			role: m.role === "assistant" ? "model" : "user",
			parts: [{ text: m.content }]
		}))
	];
	const res = await fetch(url, {
		method: "POST",
		headers: { "Content-Type": "application/json" },
		body: JSON.stringify({
			contents,
			generationConfig: {
				temperature: .6,
				maxOutputTokens: 1024
			}
		}),
		signal: AbortSignal.timeout(18e3)
	});
	if (!res.ok) {
		const errorBody = await res.text();
		throw new Error(`Gemini API returned status ${res.status}: ${errorBody}`);
	}
	const text = (await res.json()).candidates?.[0]?.content?.parts?.[0]?.text;
	if (!text) throw new Error("No text candidate returned by Gemini model.");
	return text.trim();
}
/**
* Local Ollama Client
*/
async function callOllamaApi(host, systemPrompt, messages) {
	const res = await fetch(`${host}/api/chat`, {
		method: "POST",
		headers: { "Content-Type": "application/json" },
		body: JSON.stringify({
			model: process.env["OLLAMA_MODEL"] || "llama3",
			stream: false,
			messages: [{
				role: "system",
				content: systemPrompt
			}, ...messages.slice(-8)]
		}),
		signal: AbortSignal.timeout(3e4)
	});
	if (!res.ok) throw new Error(`Ollama returned status ${res.status}`);
	return (await res.json()).message?.content || "";
}
/**
* Local LM Studio Client
*/
async function callLmStudioApi(host, systemPrompt, messages) {
	const res = await fetch(`${host}/v1/chat/completions`, {
		method: "POST",
		headers: { "Content-Type": "application/json" },
		body: JSON.stringify({
			messages: [{
				role: "system",
				content: systemPrompt
			}, ...messages.slice(-8)],
			temperature: .7,
			max_tokens: 1e3
		}),
		signal: AbortSignal.timeout(3e4)
	});
	if (!res.ok) throw new Error(`LM Studio returned status ${res.status}`);
	return (await res.json()).choices?.[0]?.message?.content || "";
}
/**
* Helper to match query keywords with slide numbers or page markers in extracted text
*/
function detectDocumentCitations(extractedText, query) {
	if (!extractedText || !query) return [];
	const citations = [];
	const queryWords = query.toLowerCase().split(/\s+/).filter((w) => w.length > 3);
	const slideRegex = /### Slide (\d+):[^\n]*\n([\s\S]*?)(?=(?:### Slide \d+:|$))/g;
	let match;
	while ((match = slideRegex.exec(extractedText)) !== null) {
		const slideNum = match[1];
		const slideContent = match[2];
		if (slideNum && slideContent) {
			const lower = slideContent.toLowerCase();
			if (queryWords.some((w) => lower.includes(w)) && citations.length < 3) citations.push({
				label: `Slide ${slideNum}`,
				textSnippet: slideContent.trim().slice(0, 120)
			});
		}
	}
	return citations;
}
